<?php
require_once __DIR__ . '/../includes/auth.php'; require_login(); $active_menu='reports';$rows=all_rows("SELECT s.service_id,s.service_name,COUNT(a.appointment_id) booking_count,COALESCE(SUM(CASE WHEN p.payment_status IN ('Paid','Partially Paid') THEN p.amount ELSE 0 END),0) revenue_generated FROM services s LEFT JOIN appointments a ON a.service_id=s.service_id LEFT JOIN payments p ON p.appointment_id=a.appointment_id GROUP BY s.service_id,s.service_name ORDER BY booking_count DESC,revenue_generated DESC,s.service_name");$page_title='Popular Services Report';require __DIR__.'/../includes/header.php';
?>
<h2 class="print-heading">Popular Services Report</h2><?php require __DIR__.'/../includes/report_nav.php';?><div class="card shadow-sm table-card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Rank</th><th>Service</th><th>Number of bookings</th><th>Revenue generated</th></tr></thead><tbody><?php foreach($rows as $index=>$row):?><tr><td><?= $index+1?></td><td><?=e($row['service_name'])?></td><td><?= (int)$row['booking_count']?></td><td><?=money($row['revenue_generated'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';
